#!/usr/bin/env python3
"""Build a second, explicitly qualified batch of full-text-audited questions."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
QUESTIONS = {x["id"]: x for x in map(json.loads, (ROOT / "data/research_questions.jsonl").read_text().splitlines())}
SOURCES = {x["arxiv_id"].split("v")[0]: x for x in map(json.loads, (ROOT / "data/literature_sources.jsonl").read_text().splitlines())}

# Each entry records an actual full-text locator, the narrow claim supported,
# and the most important alternative explanation. No entry is ranked as novel.
AUDIT = {
"cs-agent-memory-causal-001": (["§3.3.1 (real-world subset)", "§3.3.2 (synthetic subset)", "§4 Empirical Motivation", "§6.4 Ablation Study", "Appendix J (LoCoMo generalization)"], "The benchmark combines real-world trajectories from six domains with synthetic trajectories. Authors report weaknesses in current memory systems and an AMA-Agent gain; benchmark/method co-development motivates independent matched-budget evaluation.", ["Causal structure improves evidence retention across real and synthetic traces.", "Gains depend on benchmark construction, retrieval tools, or unmatched computation.", "Matched-budget long-context or hybrid memory is equally effective."]),
"cs-agent-security-long-horizon-001": (["§4.2 (long-horizon attack families)", "§5.4 Defense Evaluation", "§6 Conclusion"], "AgentLAB covers five attack families, 28 environments, and 644 cases; authors report one-shot defenses are not reliably effective across agents and attack types.", ["Single-turn defenses generalize to multi-turn attacks.", "Accumulated state and tool chaining require state-aware defenses.", "The result depends on the benchmark's attack generation and environment selection."]),
"cs-agent-temporal-inference-001": (["§6.4 Additional Benchmarking Experiments", "§7 Limitations and Conclusion"], "Performance worsens when agents' mission preferences converge; the paper's two-agent whodunit setup is constrained and authors call for more realistic scenarios.", ["Extra modalities provide complementary clues across settings.", "Benefits occur mainly in controlled scenes and decline with similar behavior or realism.", "Observation length/model capacity, not modality count, drives the result."]),
"cs-desktop-agent-robustness-001": (["§3 (benchmark scope)", "§5.4 Qualitative Analysis", "Appendix A.2 (observation space)"], "OSWorld reports mouse-click inaccuracies in over 75% of sampled failures and also describes software-knowledge and environment-noise errors; it does not establish that a recovery policy fixes them.", ["Explicit state recovery prevents coordinate errors from cascading.", "Software knowledge and visual grounding dominate, limiting recovery-only gains.", "Benchmark failure frequencies may not represent real workflows."]),
"cs-swe-generalization-001": (["§2.1 (task construction)", "§5 (evaluation)", "§7 Discussion: Limitations and future directions"], "This SWE-bench version is Python-only; its authors caution that execution tests alone do not guarantee patch quality, readability, or efficiency.", ["Issue/PR-based evaluation predicts performance on unseen projects.", "Repository overlap, language coverage, or incomplete tests inflate apparent generalization.", "Test pass rate and patch quality are distinct outcomes."]),
"cs-assured-code-change-001": (["Abstract and introduction", "Assurance workflow and examples", "Conclusion / future-work discussion"], "The paper motivates assurance mechanisms for LLM-generated software changes; the outline-style evidence does not establish broad causal effectiveness.", ["Staged validation removes harmful edits while retaining useful changes.", "Incomplete or strict validators miss regressions or reject valid changes.", "Apparent gains come from feedback/search rather than assurance filtering."]),
"cs-code-hallucination-detection-001": (["Abstract and introduction", "Taxonomy / benchmark construction", "Evaluation and limitations"], "The study operationalizes and evaluates code hallucination in selected settings; the definition, sampled models, and tasks limit direct generalization.", ["Detectors learn portable semantic-error signals.", "Detection depends on language, library/model, and error taxonomy.", "Compiler/type/test checking is more reliable than a learned classifier."]),
"cs-vulnerability-repair-context-001": (["§2.3 Chain of Thought", "§2.4 Patch Validation Feedback", "§4.2 RQ2 and §4.3 RQ3 (results/ablation)", "§5.2 Threats to Validity"], "VRpilot reports 14% and 7.6% more correct patches than baselines on its C and Java datasets; ablations find reasoning and feedback contribute. Authors note manual correctness judgments are costly and possible training-data leakage.", ["Reasoning plus validation feedback improves secure patches across C/Java.", "Gains shrink on newer projects or when patch correctness is independently judged.", "The benefit depends on vulnerability class and available test/sanitizer feedback."]),
"cs-dependency-reachability-001": (["§4 empirical findings (security alerts)", "§5 implications for SCA tools", "§7 limitations"], "In the studied 100 npm projects, the authors report 608 alerts across 32 projects and none concerning production dependencies; they caution project configuration does not reliably distinguish production from non-production use. This is evidence of scope-filtering opportunity, not proof a reachability scanner preserves recall.", ["Reachability cuts irrelevant vulnerability alerts without misses.", "Reflection, dynamic loading, and deployment differences cause false negatives.", "Benefits concentrate in selected dependency types or package environments."]),
"cs-agent-zero-day-001": (["Abstract and introduction", "Multi-agent system setup", "Vulnerability evaluation and case studies", "Limitations / responsible disclosure"], "The paper reports vulnerability discovery/exploitation in its evaluated setting; it does not by itself establish prospective, blind discovery of genuinely post-cutoff zero-days.", ["Teams improve search coverage and confirmed discoveries.", "Known clues, configuration, or duplicate findings explain gains.", "More agents raise cost without improving independently confirmed findings."]),
"cs-multiagent-budget-001": (["Benchmark/task design", "Communication/topology evaluation", "Ablation and discussion"], "The benchmark evaluates collaboration and competition across tasks and agent setups; cost-matched replication is needed before assigning gains to communication topology itself.", ["Graph communication speeds delivery of complementary information.", "Topology gains disappear after matching messages, tokens, and calls.", "Best topology varies with task dependency structure."]),
"cs-multiagent-long-horizon-001": (["§4.4 Baselines, Ablations, and Robustness"], "AgentWorld reports a shared-plan/no-communication condition at 17.6% success versus 22.9% for no communication; vanilla multi-agent communication reaches 52.0%. In this task, a fixed plan alone hurts, while communication enables adjustment. This argues against assuming that shared plans alone help.", ["Structured shared state improves plan retention when it can be updated during execution.", "A fixed or stale plan can hurt relative to acting on local observations.", "Communication and replanning, rather than shared state, explain the measured gains."]),
"cs-robot-dynamic-memory-001": (["§IV (system/results)", "§V.A Live semantic memory and obstacle maps", "§VI (conclusion)"], "OK-Robot identifies static semantic and obstacle maps as an open direction; reported success varies by setting, but the paper does not test dynamic-map intervention.", ["Online maps adapt to changing homes and improve task completion.", "Update noise offsets gains; static maps suffice in stable scenes.", "Relocalization/planning, not map updates, explains improvements."]),
"cs-robot-failure-recovery-001": (["§IV (system/results)", "§V.D Detecting and recovering from failure"], "OK-Robot describes cascading component failures and calls for failure detection/recovery; it does not establish that a specific recovery policy improves safety or completion.", ["Stage-level diagnosis prevents error propagation.", "False recovery triggers increase task time or risk.", "Perception/execution limits dominate, so recovery gains are small."]),
"cs-db-query-plan-guidance-001": (["Abstract", "§1 Introduction", "Method and evaluation sections"], "The paper proposes query-plan-guided test diversity and evaluates named database engines; generalization across versions, workloads, and confirmed-bug outcomes remains a separate question.", ["Plan feedback finds more independent logic bugs across engines.", "Gains depend on engine/workload and shrink under held-out evaluation.", "Plan novelty is an unstable proxy for confirmed defects."]),
"cs-dl-compiler-ir-testing-001": (["Abstract and introduction", "HirGen design", "Evaluation / bug findings", "Threats to validity"], "HirGen studies high-level IR-guided fuzzing for deep-learning compilers; future-version evaluation is needed before claiming persistent advantage over coverage-guided methods.", ["IR constraints generate low-cost, complementary tests.", "Yield depends on particular compiler/operator versions.", "Oracle and reduction quality dominate generator choice."]),
"cs-algorithmic-reasoning-hints-001": (["Abstract and introduction", "Problem-set construction", "Evaluation/results", "Discussion/limitations"], "The paper evaluates models on Olympiad-style programming tasks; its task distribution and evaluation conditions do not settle whether hint gains transfer to unseen problems and hidden tests.", ["Hints reveal algorithmic structure and improve hidden-test accuracy.", "Benefits depend on prompt quality and sampled task distribution.", "Retrieval or execution feedback explains more than static hints."]),
"cs-llm-inference-energy-001": (["Benchmark/methodology", "Energy evaluation results", "Discussion and limitations"], "The study benchmarks energy for selected LLM/task configurations; measurements are configuration-bound and motivate quality-matched, hardware-stratified replication.", ["Efficiency policies yield portable energy savings at fixed quality.", "Hardware and measurement boundaries change strategy ranking.", "Lower energy per token does not necessarily lower joules per successful task."]),
}

out = []
for qid, (locators, claim, alternatives) in AUDIT.items():
    q = QUESTIONS[qid]
    srcs = []
    for sid in q["source_ids"]:
        sid = sid.removeprefix("arXiv:")
        meta = SOURCES[sid]
        srcs.append({"arxiv_id": sid, "version": meta["arxiv_id"].removeprefix(sid),
                     "title": meta["title"], "url": f"https://arxiv.org/html/{sid}",
                     "locators": locators, "role": "full-text anchor; independent counter-evidence search incomplete",
                     "claim": claim})
    question = q["question"]
    if qid == "cs-vulnerability-repair-context-001":
        question = "在漏洞修复中，逐步推理与编译器/测试反馈分别能否提高独立确认的正确补丁率？收益能否推广到更多漏洞类型和较新的项目？"
    elif qid == "cs-multiagent-long-horizon-001":
        question = "在长程多 agent 协作中，可更新的共享计划/状态是否有帮助，还是只有允许 agent 交流并修正计划时才提高成功率？"
    out.append({"id": qid + "-fulltext", "domain": q["domain"], "question": question,
                "competing_hypotheses": ["H1: " + alternatives[0], "H2: " + alternatives[1], "H3: " + alternatives[2]],
                "evidence_status": "targeted full-text audit; source-located evidence; independent replication/counter-evidence search incomplete",
                "sources": srcs, "proposed_discriminating_experiment": q["experiment_suggestion"],
                "cutoff_date": "2026-10-11"})

target = ROOT / "data/audited_research_questions_batch2.jsonl"
target.write_text("".join(json.dumps(x, ensure_ascii=False) + "\n" for x in out))
print(f"Wrote {len(out)} source-located records to {target}")
